import {readJSON} from './load-resource.js';
import {applyMoonIllustration,moonIllustrationCaption} from './moon-illustration.js';
import {DWARF_MAPS,DWARF_OBSERVATIONS} from './dwarf-maps.js';
import {partialCoverage} from './moon-maps.js';
import {bodyStory} from './body-stories.js';
import {dwarfCharacteristics, satelliteProfile} from './body-profile.js';
import * as THREE from './vendor/three.module.js';
export function createDwarfSystem(env){
 const group=new THREE.Group();env.scene.add(group);group.visible=false;let data=null,objects=[],targetBody=null;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const clear=()=>{group.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});group.clear();objects=[];targetBody=null;};
 function fit(object,radius){targetBody=object;const r=radius||.18;const outerRadius=r*Math.max(object.scale.x,object.scale.y,object.scale.z);env.controls.minDistance=Math.max(.00001,r*1.6,outerRadius*1.08);env.fly(object.position.clone().add(new THREE.Vector3(r*2,r*1.4,r*4.4)),object.position.clone());}
 function show(id){const dwarf=data?.find(x=>x.id===id);if(!dwarf)return;env.enter(id);clear();group.visible=true;const unit=dwarf.radiusKm/3.3;const map=DWARF_MAPS[id], observation=DWARF_OBSERVATIONS[id];
  const body=new THREE.Mesh(new THREE.SphereGeometry(3.3,80,56),new THREE.MeshStandardMaterial({map:map?env.texture(map.texture):null,color:map?0xffffff:observation?.color||dwarf.color||0x9f9b94,roughness:1}));if(id==='pluto')partialCoverage(body.material);group.add(body);if(dwarf.axesKm){const k=Math.cbrt(dwarf.axesKm.reduce((a,b)=>a*b,1));const [a,b,c]=dwarf.axesKm;body.scale.set(a/k,c/k,b/k);}
  if(observation?.ring){
   const {radiusKm,widthKm}=observation.ring;
   const ring=new THREE.Mesh(new THREE.RingGeometry((radiusKm-widthKm/2)/unit,(radiusKm+widthKm/2)/unit,160),
    new THREE.MeshBasicMaterial({color:0xb8b2aa,side:THREE.DoubleSide,transparent:true,opacity:.68,depthWrite:false}));
   ring.rotation.x=-Math.PI/2;
   group.add(ring);
  }
  const details=env.details;details.innerHTML='<p class="latin">КАРЛИКОВАЯ ПЛАНЕТА</p><h2>'+esc(dwarf.name)+'</h2>'+bodyStory(id)+dwarfCharacteristics(dwarf)+'<p class="description">'+esc(dwarf.description||'')+'</p>'+'<p class="fine">'+(map?esc(map.note):'Нейтральная научная модель: подробная фотокарта поверхности недоступна. Рельеф не выдуман.')+' Известные размеры спутников согласованы с радиусом родительского тела. Неизвестный размер — точечный маркер. Круговые орбиты показывают средние расстояния, не текущие положения.</p><div id="dwarf-moons"></div><div id="dwarf-moon-info"></div>';
  for(const [i,m] of dwarf.moons.entries()){
   const measure=env.measure(m.officialName||m.name,m.key),radius=measure?.radiusKm>0?measure.radiusKm/unit:null,a=m.aKm||Number(m.availableOrbit?.a)||null,period=m.periodDays||Math.abs(Number(m.availableOrbit?.per))/24||null;
   let obj=null;if(a){obj=radius?new THREE.Mesh(new THREE.SphereGeometry(radius,64,40),new THREE.MeshStandardMaterial({color:0xb0aaa2,roughness:1,map:m.officialName==='Charon'?env.texture('charon-hd'):null})):new THREE.Points(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3()]),new THREE.PointsMaterial({size:6,sizeAttenuation:false,color:0xa9c5db}));group.add(obj);objects.push({object:obj,a:a/unit,phase:i*2.399,period:period||null,radius});const pts=[];for(let j=0;j<=240;j++){const angle=j/240*Math.PI*2;pts.push(new THREE.Vector3(Math.cos(angle)*a/unit,0,Math.sin(angle)*a/unit));}group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),new THREE.LineBasicMaterial({color:0x539bd1,transparent:true,opacity:.28})));}
   const button=document.createElement('button');button.className='moon-row';button.textContent=(m.name||m.officialName)+' · '+(measure?.radiusKm?'R = '+measure.radiusKm+' км':'размер неизвестен');button.onclick=()=>{if(!obj){env.catalog({...m,parent:dwarf.name,confirmed:true,sourceObject:m.sizeSource||dwarf.source});return;}if(obj.isMesh&&!obj.material.map){if(measure?.semiaxesKm)obj.scale.set(...measure.semiaxesKm.map(axis=>axis/measure.radiusKm));applyMoonIllustration(obj,{key:m.key||m.name,radius,radiusKm:measure?.radiusKm,illustrative:location.hash==="#illustrative",measuredShape:!!measure?.semiaxesKm});}fit(obj,radius);env.title('СПУТНИК · '+dwarf.name,m.name||m.officialName,measure?.radiusKm?'Радиус '+measure.radiusKm+' км · реальное отношение размеров':'Точечный маркер · физический размер неизвестен','СПУТНИК');details.querySelector('#dwarf-moon-info').innerHTML='<h3>'+esc(m.name||m.officialName)+'</h3>'+satelliteProfile({...m,parent:dwarf.name},{measure})+'<p class="fine">'+(a?'Среднее расстояние от центра: '+a.toLocaleString('ru-RU')+' км. ':'Орбитальные данные не подключены: объект не размещён произвольно. ')+(measure?.radiusKm?'Радиус: '+measure.radiusKm+' км. ':'Размер неизвестен; это маркер, не модель измеренного размера.')+'</p>'+moonIllustrationCaption(obj)+env.photo(m.officialName||m.name);};details.querySelector('#dwarf-moons').append(button);
  }
  if(observation){
   details.insertAdjacentHTML("beforeend",
    `<figure class="dwarf-observation"><img src="./photos/${observation.image}.jpg" alt="${observation.caption}" loading="lazy"><figcaption>${observation.caption} ${observation.credit}. Снимок системы, детали поверхности не различимы.</figcaption></figure>`);
  }
  env.installLight(group);update(0);env.title('МАЛЫЕ ТЕЛА',dwarf.name,'Карликовая планета и её спутники','КАРЛИКОВАЯ ПЛАНЕТА');targetBody=body;env.controls.minDistance=4;const max=objects.reduce((n,x)=>Math.max(n,x.a),10);fit(body,3.3);const overview=document.createElement('button');overview.className='moon-row';overview.textContent='Вся система и орбиты спутников ↗';overview.onclick=()=>{targetBody=body;env.controls.minDistance=4;env.fly(new THREE.Vector3(0,max*1.5,max*3));};details.querySelector('#dwarf-moons').before(overview);const close=document.createElement('button');close.className='moon-row';close.textContent='Рассмотреть '+dwarf.name+' ↗';close.onclick=()=>fit(body,3.3);overview.before(close);details.scrollTop=0;
 }
 function update(days){for(const item of objects){const old=item.object.position.clone(),a=item.phase+(item.period?days/item.period*Math.PI*2:0);item.object.position.set(Math.cos(a)*item.a,0,Math.sin(a)*item.a);if(targetBody===item.object){const move=item.object.position.clone().sub(old);env.camera.position.add(move);env.controls.target.add(move);}}}
 async function mount(){data=await readJSON('./dwarfs.json');const panel=document.querySelector('#object-panel-dwarfs');for(const d of data){const button=document.createElement('button');button.className='belt-button dwarf-button';button.dataset.dwarf=d.id;button.innerHTML='<span class="dwarf-icon dwarf-icon-'+d.id+'" aria-hidden="true"></span><span>'+esc(d.name)+'</span>';button.title=d.name+(DWARF_MAPS[d.id]?' · карта космической миссии':' · нейтральная научная модель');button.onclick=()=>show(d.id);panel.append(button);}return data;}
 return {mount,show,update,setMoonsVisible(visible){objects.forEach(x=>x.object.visible=visible);},setOrbitsVisible(visible){group.children.filter(x=>x.isLine).forEach(x=>x.visible=visible);},top(){const pos=targetBody?.position.clone()||new THREE.Vector3();const r=targetBody?.geometry?.parameters?.radius||3.3;env.fly(pos.clone().add(new THREE.Vector3(0,r*6,.001)),pos);},hide(){group.visible=false;targetBody=null;},reset(){if(targetBody)fit(targetBody,targetBody.geometry?.parameters?.radius||3.3);}};
}
